#!/usr/bin/env bash
# gate-all.sh — runs fidelity-gate.sh --skip-checkui for every beat in _kit/manifest.tsv,
# using each beat's own gate --surface value. Generated by kit-init.sh; safe to re-run any time.
set -uo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
KIT="${KIT_DIR:-$HOME/.claude/skills/keynote-prototype}"
GATE="$KIT/assets/tools/fidelity-gate.sh"
MANIFEST="$PROJECT_DIR/_kit/manifest.tsv"

if [[ ! -f "$GATE" ]]; then
  echo "ERROR: fidelity-gate.sh not found at $GATE (set KIT_DIR if the kit lives elsewhere)" >&2
  exit 2
fi
if [[ ! -f "$MANIFEST" ]]; then
  echo "ERROR: manifest not found at $MANIFEST" >&2
  exit 2
fi

WORST=0
RESULTS=()
while IFS=$'\t' read -r beat_id screen_type folder gate_surface page_rel viewport; do
  [[ -z "$beat_id" || "$beat_id" == \#* ]] && continue
  page="$PROJECT_DIR/$page_rel"
  out="$PROJECT_DIR/$folder/_gate/$beat_id"
  # manifest column 6: the reference's css viewport (kit-init id:type@WxH). Wide captures shoot at DPR 1.
  vp_args=()
  if [[ -n "${viewport:-}" ]]; then
    vp_args=(--viewport "$viewport")
    (( ${viewport%%x*} >= 2000 )) && vp_args+=(--dpr 1)
  fi
  echo "[gate-all] $beat_id ($screen_type) --surface $gate_surface ${vp_args[*]+${vp_args[*]}} -> $page"
  bash "$GATE" "$page" --surface "$gate_surface" ${vp_args[@]+"${vp_args[@]}"} --out "$out" --skip-checkui
  rc=$?
  case $rc in
    0) label="PASS";; 1) label="WARN";; 2) label="FAIL";; *) label="ERROR($rc)";;
  esac
  RESULTS+=("$beat_id|$screen_type|$gate_surface|$rc|$label")
  (( rc > WORST )) && WORST=$rc
done < "$MANIFEST"

echo
echo "[gate-all] Summary"
printf '%-6s %-18s %-22s %-5s %s\n' "Beat" "Type" "Surface" "rc" "Result"
for r in "${RESULTS[@]}"; do
  IFS='|' read -r b t s rc label <<< "$r"
  printf '%-6s %-18s %-22s %-5s %s\n' "$b" "$t" "$s" "$rc" "$label"
done
exit "$WORST"
